using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using SwissEphNet.Conformance.Tests.Corpus;
using SwissEphNet.Conformance.Tests.KnownFail;
using Xunit;

namespace SwissEphNet.Conformance.Tests;

/// <summary>
/// Reads/validates Tests/conformance/value-mismatch-triage.tsv: the point-in-time record of why
/// each VALUE-MISMATCH row in known-fail.tsv fails, measured 2026-11-24 against upstream
/// v2.10.04 (e308765d). The official setest/t.exp at that commit was regenerated by upstream,
/// so the earlier ledger (668 rows, measured 2026-08-02 against the previous t.exp) no longer
/// described the corpus and was replaced.
///
/// Method. Upstream's own setest at e308765d was built with gcc 13.3 on Ubuntu 24.04
/// (-g -Wall -fPIC, as the shipped Makefile does) and run in generate mode (setest -g t) with
/// SE_EPHE_PATH holding exactly the 8 files in required-ephemeris-files.tsv, the same data set
/// this harness uses. That produced a C-generated t.exp. Two harness arrays in
/// setest/suite_09_rise.c were widened first because setest overflows them: dobs[5] to dobs[6]
/// (swe_heliacal_ut, swe_heliacal_pheno_ut and swe_vis_limit_mag take dobs[6], and
/// default_heliacal_parameters() writes dobs[5], swehel.c:1352) and xxtret[10] to xxtret[50]
/// (swe_heliacal_pheno_ut writes up to darr[27]). The port's harness was then run against both
/// corpora, with the setest v2.10.04 comparison rules (tolerances.c, f952691; per-testcase
/// precision reset) and the file-scope statics of suite_NN_*.c mirrored, and the rows whose
/// values differ from the C-generated corpus beyond the setest tolerance were replayed through the
/// MSVC-built C at e308765d.
///
/// Result. Every one of the 377 rows is DRIFT: no row is a port defect. 260 rows
/// (note DATA-ENV) pass against the C-generated corpus, so the C on the declared data set
/// reproduces the port and the official t.exp's value comes from a different data environment
/// (it was generated with de441.eph, the EOP files and the full ephemeris set). 91 rows
/// (SERR-PATH) are iterations whose era ephemeris file (seplm36, sepl_30, sepl_00, seasm36, ...)
/// is not among the 8 files: against the official t.exp the return code and every value differ,
/// because the reference found the file and the port, like the C on this data set, did not. They match the C-generated corpus except for the ephemeris directory
/// embedded in the serr text of a "not found in PATH '...'" message, which CheckS compares raw.
/// That is why they have their own tag, rather than being folded into DATA-ENV, which means
/// "passes against the C-generated corpus outright". 26 rows (LIBM-PLATFORM) differ numerically
/// from the C-generated corpus, and the MSVC-built C equals the port exactly (54 of 54 compared
/// fields), so the Linux-generated value differs only through glibc libm against the Windows CRT.
/// Unlike known-fail.tsv, this file is not regenerated from a live run: it is a snapshot, kept
/// as the evidence.
///
/// The classification column is DRIFT or PORT-DEFECT. The earlier ledger had four PORT-DEFECT
/// rows (1.1.377, 379, 383, 385: the missing JD-range guard on SE_INTP_PERG). That guard is
/// fixed (Sweph.cs, the SE_INTP_PERG branch of swe_calc, mirroring SE_INTP_APOG), and there are
/// no PORT-DEFECT rows now. The guard has no dedicated unit test in Tests/SwissEphNet.Tests;
/// it is covered by those four conformance iterations, which are still in t.exp (rc -1,
/// "interpolated apsides not available at ...") and pass, so they are in neither category of
/// known-fail.tsv. <see cref="FormerPortDefectIterations_PassTheConformanceCorpus"/> pins that.
/// <see cref="PortDefectRows_StayAbsentFromKnownFail"/> is the general guard for any future
/// PORT-DEFECT row, and is vacuous while there are none.
/// </summary>
public class ValueMismatchTriageTests
{
    private const string FileName = "value-mismatch-triage.tsv";
    private static readonly string[] Header =
        ["suite", "testcase", "iteration", "magnitude_key", "classification", "note", "fields (texp=official setest/t.exp at e308765d, port=SwissEphNet output, c=C-generated setest corpus: upstream setest at e308765d built with gcc 13.3 on Ubuntu 24.04 and run with -g against the 8 files in required-ephemeris-files.tsv, after widening dobs[5] to dobs[6] and xxtret[10] to xxtret[50] in suite_09_rise.c, msvc=MSVC-built C at e308765d for the LIBM-PLATFORM rows only, AGREES-PORT = c is within the setest tolerance (tolerances.c) of port, measured 2026-11-24)"];

    private static readonly HashSet<string> AllowedClassifications = new(StringComparer.Ordinal) { "DRIFT", "PORT-DEFECT" };

    private sealed record TriageRow(IterationKey Key, string MagnitudeKey, string Classification, string Note, string Fields);

    private static string ResolvePath() => Path.Combine(RepoLocator.ConformanceDataDir, FileName);

    private static IReadOnlyList<TriageRow> Load(string path)
    {
        using var reader = new StreamReader(path);
        var headerLine = reader.ReadLine();
        Assert.NotNull(headerLine);
        Assert.Equal(Header, headerLine!.Split('\t'));

        var rows = new List<TriageRow>();
        var seen = new HashSet<IterationKey>();
        string? line;
        var lineNumber = 1;
        while ((line = reader.ReadLine()) is not null)
        {
            lineNumber++;
            if (line.Length == 0)
            {
                continue;
            }

            // The trailing "fields" column holds many "; "-joined field diffs; split with a
            // count cap so a stray literal tab there cannot silently shift columns.
            var parts = line.Split('\t', 7);
            if (parts.Length != 7)
            {
                throw new FormatException($"{path}:{lineNumber}: expected 7 tab-separated columns, got {parts.Length}: '{line}'");
            }

            var key = new IterationKey(
                int.Parse(parts[0], CultureInfo.InvariantCulture),
                int.Parse(parts[1], CultureInfo.InvariantCulture),
                int.Parse(parts[2], CultureInfo.InvariantCulture));

            if (!seen.Add(key))
            {
                throw new FormatException($"{path}:{lineNumber}: duplicate entry for iteration {key}.");
            }

            rows.Add(new TriageRow(key, parts[3], parts[4], parts[5], parts[6]));
        }

        return rows;
    }

    [Fact]
    public void EveryRow_HasAKnownClassification_AndNonEmptyFieldsColumn()
    {
        var path = ResolvePath();
        var rows = Load(path);

        Assert.NotEmpty(rows);
        foreach (var row in rows)
        {
            Assert.Contains(row.Classification, AllowedClassifications);
            Assert.False(string.IsNullOrWhiteSpace(row.Note), $"{row.Key}: 'note' column (the cause tag) is empty.");
            Assert.False(string.IsNullOrWhiteSpace(row.Fields), $"{row.Key}: 'fields' column is empty.");
        }
    }

    /// <summary>
    /// A PORT-DEFECT row is a confirmed port bug, which is exactly what known-fail.tsv's
    /// VALUE-MISMATCH set must not hold: each porting PR removes entries and adds none. If a
    /// PORT-DEFECT row is ever recorded, it must be fixed and pruned, so it must be absent from
    /// known-fail.tsv's VALUE-MISMATCH rows. Vacuous while the ledger has no PORT-DEFECT rows,
    /// which is the case now; it stays so a future triage cannot record one and leave it failing.
    /// </summary>
    [Fact]
    public void PortDefectRows_StayAbsentFromKnownFail()
    {
        var rows = Load(ResolvePath());
        var knownFail = KnownFailList.Load(Path.Combine(RepoLocator.ConformanceDataDir, "known-fail.tsv"));

        foreach (var row in rows.Where(r => r.Classification == "PORT-DEFECT"))
        {
            if (knownFail.TryGetValue(row.Key, out var entry))
            {
                Assert.True(
                    entry.Category != FailureCategory.ValueMismatch,
                    $"{row.Key} is classified PORT-DEFECT in {FileName} but is still a VALUE-MISMATCH row in " +
                    $"known-fail.tsv ({entry.Reason}). A confirmed port defect must be fixed and pruned.");
            }
        }
    }

    /// <summary>
    /// The four iterations the previous ledger recorded as PORT-DEFECT (suite 1 testcase 1, ipl 22
    /// SE_INTP_PERG at a JD outside the Moshier lunar range) were fixed by adding the JD-range
    /// guard to the SE_INTP_PERG branch of swe_calc. There is no unit test of that guard in
    /// Tests/SwissEphNet.Tests; these iterations are its regression coverage. They are still in
    /// t.exp (rc -1) and pass, so they must be in neither category of known-fail.tsv. If the guard
    /// regressed they would fail and have to be added there, which this test refuses.
    /// </summary>
    [Fact]
    public void FormerPortDefectIterations_PassTheConformanceCorpus()
    {
        var formerPortDefects = new[]
        {
            new IterationKey(1, 1, 377),
            new IterationKey(1, 1, 379),
            new IterationKey(1, 1, 383),
            new IterationKey(1, 1, 385),
        };

        var knownFail = KnownFailList.Load(Path.Combine(RepoLocator.ConformanceDataDir, "known-fail.tsv"));
        foreach (var key in formerPortDefects)
        {
            Assert.False(
                knownFail.ContainsKey(key),
                $"{key} (SE_INTP_PERG outside the Moshier lunar range) is back in known-fail.tsv. " +
                "Its JD-range guard in Sweph.cs's SE_INTP_PERG branch has probably regressed.");
        }
    }

    /// <summary>
    /// The ledger must cover exactly the VALUE-MISMATCH keys of known-fail.tsv: no more, no
    /// fewer. A t.exp regeneration or a known-fail.tsv regeneration that changes the set must
    /// re-triage, so the two files cannot drift apart again.
    /// </summary>
    [Fact]
    public void Ledger_CoversExactlyTheValueMismatchKeysOfKnownFail()
    {
        var ledgerKeys = Load(ResolvePath()).Select(r => r.Key).ToHashSet();
        var knownFail = KnownFailList.Load(Path.Combine(RepoLocator.ConformanceDataDir, "known-fail.tsv"));
        var valueMismatchKeys = knownFail
            .Where(kv => kv.Value.Category == FailureCategory.ValueMismatch)
            .Select(kv => kv.Key)
            .ToHashSet();

        var untriaged = valueMismatchKeys.Except(ledgerKeys).OrderBy(k => k.Suite).ThenBy(k => k.TestCase).ThenBy(k => k.Iteration).ToList();
        var stale = ledgerKeys.Except(valueMismatchKeys).OrderBy(k => k.Suite).ThenBy(k => k.TestCase).ThenBy(k => k.Iteration).ToList();

        Assert.True(untriaged.Count == 0, $"{untriaged.Count} VALUE-MISMATCH row(s) in known-fail.tsv have no row in {FileName}: {string.Join(", ", untriaged.Take(20))}.");
        Assert.True(stale.Count == 0, $"{stale.Count} row(s) in {FileName} are not VALUE-MISMATCH rows in known-fail.tsv: {string.Join(", ", stale.Take(20))}.");
    }

    /// <summary>
    /// Every row this file names must correspond to a real, still-existing iteration in the
    /// current setest corpus -- catches the file quietly drifting out of sync with a t.exp
    /// regeneration (a suite/testcase/iteration renumbering) without anyone noticing, since
    /// nothing else ever reads it.
    /// </summary>
    [Fact]
    public void EveryRow_ReferencesAnIterationThatStillExistsInTheCorpus()
    {
        var rows = Load(ResolvePath());

        // Parse-only, like ConformanceSuiteTests.CorpusParsesToExpectedTotals -- this does
        // not need a full 18,919-iteration dispatch run, just the set of iteration keys t.exp
        // currently defines.
        var expPath = Path.Combine(RepoLocator.SetestDir, "t.exp");
        var doc = ExpReader.Read(expPath);

        var validKeys = new HashSet<IterationKey>();
        foreach (var suite in doc.TestSuites)
        {
            foreach (var testCase in suite.TestCases)
            {
                foreach (var iteration in testCase.Iterations)
                {
                    validKeys.Add(new IterationKey(suite.Id, testCase.Id, iteration.Id));
                }
            }
        }

        var missing = rows.Where(r => !validKeys.Contains(r.Key)).Select(r => r.Key).ToList();
        Assert.True(missing.Count == 0, $"{missing.Count} row(s) in value-mismatch-triage.tsv reference an iteration no longer in the corpus: {string.Join(", ", missing.Take(20))}.");
    }
}
